<link rel="stylesheet" href="/assets/admin-crud.css?v=<?=e((string)filemtime(__DIR__.'/../../public/assets/admin-crud.css'))?>"><div class="crud-heading"><div><p>PENGGUNA</p><h1>Kelola pengguna</h1></div></div><?php if(isset($_GET['saved'])):?><p class="ok crud-message">Pengguna berhasil disimpan.</p><?php elseif(isset($_GET['deleted'])):?><p class="ok crud-message">Pengguna berhasil dihapus.</p><?php elseif(isset($_GET['error'])):?><p class="alert crud-message"><?=e(match($_GET['error']){'self'=>'Akun yang sedang digunakan tidak dapat dihapus.','protected'=>'Pengguna tidak ditemukan atau merupakan super administrator yang dilindungi.',default=>'Pengguna tidak dapat dihapus.'})?></p><?php endif?><div class="grid2 crud-grid"><section class="card"><h2 id="user-form-title">Tambah operator</h2><form method="post" id="user-form"><input type="hidden" name="_csrf" value="<?=csrf_token()?>"><input type="hidden" name="action" value="save"><input type="hidden" name="id" id="user-id"><label>Nama<input name="name" id="user-name" required></label><label>Username<input name="username" id="user-username" required></label><label>Password<input type="password" name="password" minlength="10" placeholder="Wajib untuk pengguna baru"></label><label>Role<select name="role" id="user-role"><option value="operator">Operator</option><option value="admin">Administrator</option></select></label><label>Loket bawaan<select name="assigned_counter_id" id="user-counter"><option value="">Semua loket yang diizinkan</option><?php foreach($counters as $counter):?><option value="<?=e($counter['id'])?>"><?=e($counter['name'])?></option><?php endforeach?></select></label><fieldset><legend>Layanan yang diizinkan</legend><div class="check-grid"><?php foreach($services as $service):?><label><input type="checkbox" name="service_ids[]" value="<?=e($service['id'])?>"> <?=e($service['name'])?></label><?php endforeach?></div></fieldset><label class="media-check"><input type="checkbox" name="active" id="user-active" checked> Aktif</label><button type="submit">Simpan pengguna</button><button type="button" class="secondary" id="user-reset">Pengguna baru</button></form></section><section class="crud-table-card"><div class="crud-table-wrap"><table><thead><tr><th>Pengguna</th><th>Role</th><th>Loket</th><th>Layanan</th><th>Aksi</th></tr></thead><tbody><?php foreach($users as $item):?><tr><td><b><?=e($item['name'])?></b><small class="crud-description"><?=e($item['username'])?> · <?=$item['active']?'Aktif':'Nonaktif'?></small></td><td><?=e(ucfirst($item['role']))?></td><td><?=e($item['counter_name']??'Semua')?></td><td><?=e($item['service_names']??'-')?></td><td><div class="crud-actions"><button type="button" class="edit-user secondary" data-user='<?=e(json_encode(['id'=>$item['id'],'name'=>$item['name'],'username'=>$item['username'],'role'=>$item['role'],'counter_id'=>$item['assigned_counter_id'],'active'=>(bool)$item['active'],'services'=>array_map('intval',array_filter(explode(',',$item['service_ids']??'')))],JSON_UNESCAPED_UNICODE))?>'>Edit</button><form method="post" class="delete-form" data-name="<?=e($item['name'])?>"><input type="hidden" name="_csrf" value="<?=csrf_token()?>"><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?=e($item['id'])?>"><button type="submit" class="danger">Hapus</button></form></div></td></tr><?php endforeach?></tbody></table></div></section></div><script src="/assets/users.js?v=<?=e((string)filemtime(__DIR__.'/../../public/assets/users.js'))?>"></script><script src="/assets/admin-crud.js?v=<?=e((string)filemtime(__DIR__.'/../../public/assets/admin-crud.js'))?>"></script>
